<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
define('CLUB_CONTACT_LIBRARY_ONLY',true);require __DIR__.'/../contact.php';
set_exception_handler(function(Throwable $e):void{fwrite(STDERR,$e->getMessage()."\n".$e->getTraceAsString()."\n");exit(1);});
function contact_check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function contact_denied(callable $fn,string $message):void{try{$fn();}catch(RuntimeException|InvalidArgumentException $e){return;}throw new RuntimeException($message);}
$pdo=db();$pdo->beginTransaction();
try{
    $tag='contact-test-'.bin2hex(random_bytes(5));$input=['name'=>'Example visitor','email'=>'test@example.invalid','phone'=>'','subject'=>'Hall enquiry','category'=>'hall_hire','message'=>'Please tell me about hiring the hall.','consent'=>1];$token=bin2hex(random_bytes(32));$ip='test-'.$tag;
    unset($_SESSION['admin_id'],$_SESSION['club_user_id'],$_SESSION['club_auth_sig']);
    // No timer requirement: even immediate completion must be accepted.
    $receipt=club_contact_save(array_merge($input,['form_loaded_at'=>time()]),[],$token,$ip);$repeat=club_contact_save($input,[],$token,$ip);contact_check($receipt['id']===$repeat['id'],'Retry creates duplicate enquiry');
    $q=$pdo->prepare('SELECT COUNT(*) FROM contact_enquiries WHERE reference=?');$q->execute([$receipt['reference']]);contact_check((int)$q->fetchColumn()===1,'Duplicate stored enquiry');
    $q=$pdo->prepare('SELECT * FROM club_outbox WHERE event_key=?');$q->execute(['contact-notification-'.$receipt['id']]);$notice=$q->fetch();$payload=json_decode($notice['payload'],true);contact_check($notice['status']==='connection_required','Disabled mail claims delivery');contact_check($payload['to']==='thenettlebedclub@gmail.com'&&!isset($payload['attachments'])&&!isset($payload['message']),'Notification leaks content or routes to wrong recipient');
    $oldRecipient=club_setting('enquiry_recipient');set_setting('enquiry_recipient','routing@example.invalid');$routed=club_contact_save($input,[],bin2hex(random_bytes(32)),$ip.'route');$q=$pdo->prepare('SELECT payload FROM club_outbox WHERE event_key=?');$q->execute(['contact-notification-'.$routed['id']]);contact_check(json_decode($q->fetchColumn(),true)['to']==='routing@example.invalid','Configured recipient ignored');set_setting('enquiry_recipient',$oldRecipient);
    contact_denied(fn()=>club_contact_save(array_merge($input,['website'=>'spam']),[],bin2hex(random_bytes(32)),$ip),'Honeypot accepted');contact_denied(fn()=>club_contact_save(array_merge($input,['category'=>'attacker@example.invalid']),[],bin2hex(random_bytes(32)),$ip),'Visitor chooses notification recipient');
    $count=(int)$pdo->query('SELECT COUNT(*) FROM contact_enquiries')->fetchColumn();contact_denied(fn()=>club_contact_save($input,['name'=>['bad.exe'],'tmp_name'=>['missing'],'error'=>[UPLOAD_ERR_PARTIAL],'size'=>[1]],bin2hex(random_bytes(32)),$ip),'Invalid attachment accepted');contact_check((int)$pdo->query('SELECT COUNT(*) FROM contact_enquiries')->fetchColumn()===$count,'Failed upload left enquiry partially saved');
    for($i=0;$i<4;$i++)club_contact_save($input,[],bin2hex(random_bytes(32)),$ip);contact_denied(fn()=>club_contact_save($input,[],bin2hex(random_bytes(32)),$ip),'Source rate limit missing');
    $ids=[];foreach(['member','treasurer','publisher','administrator','handler'] as $name){$pdo->prepare("INSERT INTO club_users(full_name,email,password_hash,email_verified_at,status) VALUES(?,?,?,NOW(),'active')")->execute([$name,$tag.'-'.$name.'@example.invalid','unused']);$ids[$name]=(int)$pdo->lastInsertId();$role=$name==='handler'?'member':$name;$pdo->prepare('INSERT INTO club_user_roles(user_id,role) VALUES(?,?)')->execute([$ids[$name],$role]);}
    foreach(['member','publisher','treasurer'] as $role){$_SESSION['club_user_id']=$ids[$role];contact_check(!club_contact_can_handle('hall_hire'),$role.' can read hall enquiries');contact_denied(fn()=>club_contact_resolve($receipt['id']),$role.' can mutate hall enquiry');}
    $_SESSION['club_user_id']=$ids['treasurer'];contact_check(club_contact_can_handle('membership'),'Treasurer lacks membership correspondence access');
    $_SESSION['club_user_id']=$ids['handler'];$pdo->prepare("INSERT INTO club_enquiry_routes(user_id,category) VALUES(?,'hall_hire')")->execute([$ids['handler']]);contact_check(club_contact_can_handle('hall_hire')&&!club_contact_can_handle('membership'),'Category handler access is not scoped');$pdo->prepare('UPDATE club_users SET email_verified_at=NULL WHERE id=?')->execute([$ids['handler']]);contact_check(!club_contact_can_handle('hall_hire'),'Unverified handler bypasses capability check');contact_denied(fn()=>club_contact_resolve($receipt['id']),'Unverified handler resolves enquiry');$pdo->prepare('UPDATE club_users SET email_verified_at=NOW() WHERE id=?')->execute([$ids['handler']]);club_contact_resolve($receipt['id']);$q=$pdo->prepare('SELECT status FROM contact_enquiries WHERE id=?');$q->execute([$receipt['id']]);contact_check($q->fetchColumn()==='resolved','Assigned handler cannot resolve enquiry');
    $_SESSION['club_user_id']=$ids['administrator'];foreach(['general','membership','hall_hire'] as $category)contact_check(club_contact_can_handle($category),'Administrator lacks enquiry visibility');
    $attachment=['owner_type'=>'contact','owner_id'=>$receipt['id']];$_SESSION['club_user_id']=$ids['publisher'];contact_check(!club_attachment_allowed($attachment),'Publisher can retrieve private enquiry attachment');$_SESSION['club_user_id']=$ids['handler'];contact_check(club_attachment_allowed($attachment),'Assigned handler cannot retrieve attachment');
    echo "Contact tests passed: deduplication, honest mail state, source limit, upload rollback, category permissions and private attachments.\n";
}finally{if($pdo->inTransaction())$pdo->rollBack();unset($_SESSION['club_user_id'],$_SESSION['club_auth_sig']);}
